package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const f17Header = "# F17 — CLI-PLUGIN-COMPAT\n\n" +
	"**SPORT — Single Point of Reference Truth**\n" +
	"Auto-generated by `cli/scripts/sport/generate-f17.sh`. Do not edit manually.\n" +
	"Regenerate: `bash cli/scripts/sport/generate-f17.sh`\n\n" +
	"S58-T05. Inverse of F18: for the current CLI version, which plugins are compatible?\n\n"

var statusLabel = map[string]string{
	"eol": " **[EOL]**", "deprecated": " *[deprecated]*", "beta": " *(beta)*",
	"experimental": " *(experimental)*", "planned": " *(planned)*",
}

// nselfRoot finds the directory holding plugins/: override, else walk up from cli/.
func nselfRoot(d Deps) string {
	if v := d.Env("F17_NSELF_ROOT"); v != "" {
		return v
	}
	for dir := filepath.Dir(d.Root); dir != "/" && dir != "."; dir = filepath.Dir(dir) {
		if _, err := os.Stat(filepath.Join(dir, "plugins", "registry.json")); err == nil {
			return dir
		}
	}
	return filepath.Dir(d.Root)
}

// cliVersion reads .github/facts.json, then .github/VERSION.
func cliVersion(root string) string {
	v := ""
	if raw, err := os.ReadFile(filepath.Join(root, ".github", "facts.json")); err == nil {
		var f struct {
			Version string `json:"version"`
		}
		if json.Unmarshal(raw, &f) == nil {
			v = f.Version
		}
	}
	if v == "" {
		if raw, err := os.ReadFile(filepath.Join(root, ".github", "VERSION")); err == nil {
			v = strings.Join(strings.Fields(string(raw)), "")
		}
	}
	return strings.TrimPrefix(v, "v")
}

// runF17 ports generate-f17.sh.
func runF17(d Deps) int {
	errf := func(format string, a ...any) int {
		fmt.Fprintf(d.Stderr, "error: "+format+"\n", a...)
		return 1
	}
	rr := nselfRoot(d)
	free, pro := filepath.Join(rr, "plugins", "registry.json"), filepath.Join(rr, "plugins-pro", "registry.json")
	outFile := d.Env("F17_OUT_FILE")
	if outFile == "" {
		tmp := d.Env("TMPDIR")
		if tmp == "" {
			tmp = "/tmp"
		}
		outFile = tmp + "/F17-CLI-PLUGIN-COMPAT.md"
	}
	if strings.Contains(outFile, "/.claude/docs/sport/") {
		return errf("refusing to write to the retired .claude/docs/sport/ path: %s", outFile)
	}
	if fi, err := os.Stat(filepath.Dir(outFile)); err != nil || !fi.IsDir() {
		return errf("output directory does not exist: %s", filepath.Dir(outFile))
	}
	var plugins []plugin
	for _, p := range []string{free, pro} {
		rows, err := registryPlugins(p)
		if err != nil {
			return errf("%v", err)
		}
		plugins = append(plugins, rows...)
	}
	ver := cliVersion(d.Root)
	if ver == "" {
		return errf("cannot read the CLI version from .github/facts.json or .github/VERSION")
	}
	if len(plugins) == 0 {
		return errf("no plugin rows read from %s or %s (registries missing, unreadable or empty)", free, pro)
	}
	var b strings.Builder
	b.WriteString(f17Header)
	fmt.Fprintf(&b, "## v%s\n\n| Plugin | Status | Notes |\n|--------|--------|-------|\n", ver)
	for _, p := range plugins {
		if semverLTE(p.min, ver) && semverLTE(ver, p.max) {
			fmt.Fprintf(&b, "| %-30s | %-12s | %s |\n", p.name, p.status, statusLabel[p.status])
		}
	}
	fmt.Fprintf(&b, "\n\n## Summary\n\n- **CLI versions covered:** 1\n- **Generated:** %s\n",
		d.Now().UTC().Format("2006-01-02T15:04:05Z"))
	if err := os.WriteFile(outFile, []byte(b.String()), 0o644); err != nil {
		return errf("%v", err)
	}
	fmt.Fprintf(d.Stdout, "F17 generated for CLI v%s: %s\n", ver, outFile)
	return 0
}
